// Backward-compatibility regression: a full state saved by the 5-FX build (main a70e0d0, schema v2) must load
// identically after the FX rack grew to 7 slots (EFFECTS_SPEC sections 19-20, ROUTING_SPEC section 3 bus table).
//
// tests/golden/state_5fx_v2.xml was generated by THIS file's scenario running on main before the FX change:
//     CM_WRITE_GOLDEN=1 ./crowdmike_tests golden_state_generate
// (the generate test is a no-op unless the variable is set). It must never be regenerated from a newer build.
#include "TestHarness.h"
#include "Core/SceneBank.h"
#include "Core/StateIO.h"
#include "PluginProcessor.h"
#include <cstdlib>

using namespace crowdmike;

namespace {
struct PV { const char* id; float v; };
// Parameter IDs only (frozen), so the scenario compiles unchanged against the old and the new parameter tables.
const PV kParams[] = {
    { "input1.fxSend1", -6.0f }, { "input1.fxSend5", -9.0f }, { "input2.fxSend3", -12.0f }, { "input1.fxSendPre", 1.0f },
    { "input3.trimDb", 3.5f }, { "input16.fxSend5", -3.0f }, { "input16.trimDb", -4.5f }, { "input1.mute", 1.0f },
    { "group1.fxSend1", -12.0f }, { "group1.fxSend2", -12.0f }, { "group1.fxSend4", -18.0f }, { "group8.fxSend5", -4.0f },
    { "group2.trimDb", 2.0f }, { "group8.width", 1.5f },
    { "fx.delay.timeMs", 777.0f }, { "fx.delay.feedback", 0.5f }, { "fx.delay.mode", 2.0f }, { "fx.echo.repeats", 7.0f },
    { "fx.tape.age", 0.9f }, { "fx.reverse.chunkSec", 2.5f }, { "fx.reverse.trigMode", 3.0f }, { "fx.noise.seed", 4242.0f },
    { "fx.noise.returnDb", -6.0f }, { "master.levelDb", -3.0f }, { "out3.trimDb", -2.0f }, { "out16.delayMs", 12.5f },
    { "macro3", 0.4f }, { "bypass", 0.0f }, { "densityToSend", 0.25f },
};
constexpr int kOldBusRows = 30;       // 16 group + 10 fx + 2 playback + 2 master
constexpr int kOldTapMaster = 45, kOldTapFxNoise = 44, kOldTapOutPair7 = 54;

void setActual(CrowdMikeAudioProcessor& p, const char* id, float v) {
    auto* prm = p.getParameters().getParameter(id);
    CM_EXPECT(prm != nullptr);
    if (prm != nullptr) prm->setValueNotifyingHost(prm->convertTo0to1(v));
}
float actualOf(CrowdMikeAudioProcessor& p, const char* id) {
    auto* prm = p.getParameters().getParameter(id);
    return prm != nullptr ? prm->convertFrom0to1(prm->getValue()) : -12345.0f;
}
float busValue(int row) { return 0.01f * static_cast<float>(row + 1); }

void buildScenario(CrowdMikeAudioProcessor& p) {
    for (const auto& pv : kParams) setActual(p, pv.id, pv.v);
    auto& r = p.getRouting();
    r.setDirect(0, 0, 1.0f); r.setDirect(1, 1, 0.5f); r.setDirect(15, 15, -1.0f);
    r.setAssign(0, 0, 1.0f); r.setAssign(1, 1, 0.7f); r.setAssign(15, 7, 0.25f);
    for (int row = 0; row < kOldBusRows; ++row) r.setBus(row, 3, busValue(row));
    r.setBus(29, 15, 0.5f); r.setBus(0, 0, 1.0f); r.setBus(28, 0, 1.0f); r.setBus(29, 1, 1.0f); r.setBus(26, 2, 0.8f);
    r.setHasSavedDirect(true);
    auto& s = p.getShow();
    s.input(0).name = "Front Mic"; s.group(2).name = "Balcony Mix"; s.output(5).label = "Delay Tower";
    s.macroNames[0] = "Golden Macro";
    s.ui.fxOrder = { 4, 3, 2, 1, 0 };
    s.ui.recallScope = 0x7Fu;
    s.recorder.tracks[0].sourceId = kOldTapMaster; s.recorder.tracks[0].numChannels = 2; s.recorder.tracks[0].armed = true;
    s.recorder.tracks[1].sourceId = kOldTapFxNoise; s.recorder.tracks[1].numChannels = 2;
    s.recorder.tracks[2].sourceId = kOldTapOutPair7; s.recorder.tracks[2].numChannels = 2;
    s.macros.macros[0].count = 1;
    s.macros.macros[0].dests[0].paramIndex = ParamBank::indexForId("fx.delay.feedback");
    s.macros.macros[0].dests[0].min01 = 0.1f; s.macros.macros[0].dests[0].max01 = 0.9f;
    ControlBinding b; b.type = MidiMsgType::CC; b.channel = 2; b.number = 20; b.target = BindTarget::Param;
    b.targetIndex = ParamBank::indexForId("fx.echo.trigger"); b.mode = BindMode::Momentary;
    s.bindings.push_back(b);
    s.setLocked(ParamBank::indexForId("fx.tape.age"), true);
    p.applyShowChanges();
    p.getScenes().capture(0, "Golden A");
}

juce::File goldenFile() {
    return juce::File(__FILE__).getParentDirectory().getParentDirectory().getChildFile("golden").getChildFile("state_5fx_v2.xml");
}
}

CM_TEST(golden_state_generate) {
    if (std::getenv("CM_WRITE_GOLDEN") == nullptr) return;
    juce::ScopedJuceInitialiser_GUI gui;
    CrowdMikeAudioProcessor p;
    p.prepareToPlay(48000.0, 256);
    buildScenario(p);
    juce::MemoryBlock mb;
    p.getStateInformation(mb);
    auto xml = juce::AudioProcessor::getXmlFromBinary(mb.getData(), static_cast<int>(mb.getSize()));
    CM_EXPECT(xml != nullptr);
    if (xml == nullptr) return;
    goldenFile().getParentDirectory().createDirectory();
    CM_EXPECT(goldenFile().replaceWithText(xml->toString()));
}

CM_TEST(golden_state_5fx_loads_identically) {
    juce::ScopedJuceInitialiser_GUI gui;
    const auto file = goldenFile();
    CM_EXPECT(file.existsAsFile());
    auto xml = juce::XmlDocument::parse(file);
    CM_EXPECT(xml != nullptr);
    if (xml == nullptr) return;
    CM_EXPECT(xml->getIntAttribute("schemaVersion") == 2);

    juce::MemoryBlock mb;
    juce::AudioProcessor::copyXmlToBinary(*xml, mb);
    CrowdMikeAudioProcessor p;
    p.setStateInformation(mb.getData(), static_cast<int>(mb.getSize()));
    p.prepareToPlay(48000.0, 256);

    // ---- parameters (every scenario value, by frozen ID)
    for (const auto& pv : kParams) CM_EXPECT_NEAR(actualOf(p, pv.id), pv.v, 0.02);
    // ---- the new FX slots and their sends come up at defaults
    CM_EXPECT_NEAR(actualOf(p, "input1.fxSend6"), -80.0, 1e-3);
    CM_EXPECT_NEAR(actualOf(p, "input16.fxSend7"), -80.0, 1e-3);
    CM_EXPECT_NEAR(actualOf(p, "group8.fxSend6"), -80.0, 1e-3);
    CM_EXPECT(actualOf(p, "fx.reverb.on") == 0.0f);
    CM_EXPECT(actualOf(p, "fx.multi.on") == 0.0f);

    // ---- routing: every legacy bus row keeps its meaning, the four new FX rows are silent
    const auto& r = p.getRouting();
    CM_EXPECT_NEAR(r.getDirect(1, 1), 0.5, 1e-3);
    CM_EXPECT_NEAR(r.getDirect(15, 15), -1.0, 1e-3);
    CM_EXPECT_NEAR(r.getAssign(1, 1), 0.7, 1e-3);
    CM_EXPECT_NEAR(r.getAssign(15, 7), 0.25, 1e-3);
    for (int row = 0; row < kOldBusRows; ++row) CM_EXPECT_NEAR(r.getBus(row, 3), busValue(row), 1e-3);
    CM_EXPECT_NEAR(r.getBus(29, 15), 0.5, 1e-3);
    CM_EXPECT_NEAR(r.getBus(0, 0), 1.0, 1e-3);
    CM_EXPECT_NEAR(r.getBus(28, 0), 1.0, 1e-3);
    CM_EXPECT_NEAR(r.getBus(29, 1), 1.0, 1e-3);
    CM_EXPECT_NEAR(r.getBus(26, 2), 0.8, 1e-3);
    CM_EXPECT(RoutingState::busRowForGroup(7, 1) == 15);
    CM_EXPECT(RoutingState::busRowForFx(4, 1) == 25);
    CM_EXPECT(RoutingState::busRowForPlayback(0) == 26);
    CM_EXPECT(RoutingState::busRowForMaster(0) == 28);
    CM_EXPECT(RoutingState::busRowForMaster(1) == 29);
    for (int row = kBusSrcCount - 4; row < kBusSrcCount; ++row)
        for (int o = 0; o < kMaxOutputs; ++o) CM_EXPECT(r.getBus(row, o) == 0.0f);
    CM_EXPECT(r.hasSavedDirect());

    // ---- show model
    auto& s = p.getShow();
    CM_EXPECT(s.input(0).name == "Front Mic");
    CM_EXPECT(s.group(2).name == "Balcony Mix");
    CM_EXPECT(s.output(5).label == "Delay Tower");
    CM_EXPECT(s.macroNames[0] == "Golden Macro");
    const std::array<int, 5> legacyOrder { 4, 3, 2, 1, 0 };
    for (int k = 0; k < 5; ++k) CM_EXPECT(s.ui.fxOrder[static_cast<size_t>(k)] == legacyOrder[static_cast<size_t>(k)]);
    CM_EXPECT(s.ui.fxOrder[5] == 5 && s.ui.fxOrder[6] == 6);   // the new slots are appended after a 5-entry legacy order
    CM_EXPECT(s.ui.recallScope == 0x7Fu);
    // recorder taps keep their ids (Master 45, Noise return 44, Out 15-16 = 54) and still resolve to the same sources
    CM_EXPECT(s.recorder.tracks[0].sourceId == kOldTapMaster);
    CM_EXPECT(s.recorder.tracks[1].sourceId == kOldTapFxNoise);
    CM_EXPECT(s.recorder.tracks[2].sourceId == kOldTapOutPair7);
    CM_EXPECT(s.macros.macros[0].count == 1);
    CM_EXPECT(s.macros.macros[0].dests[0].paramIndex == ParamBank::indexForId("fx.delay.feedback"));
    CM_EXPECT(s.bindings.size() == 1 && s.bindings[0].targetIndex == ParamBank::indexForId("fx.echo.trigger"));
    CM_EXPECT(s.isLocked(ParamBank::indexForId("fx.tape.age")));

    // ---- re-saving writes the legacy 30-row bus block byte-identically (old builds can still read new saves)
    juce::MemoryBlock again;
    p.getStateInformation(again);
    auto xml2 = juce::AudioProcessor::getXmlFromBinary(again.getData(), static_cast<int>(again.getSize()));
    CM_EXPECT(xml2 != nullptr);
    if (xml2 != nullptr) {
        auto* r1 = xml->getChildByName("Routing");
        auto* r2 = xml2->getChildByName("Routing");
        CM_EXPECT(r1 != nullptr && r2 != nullptr);
        if (r1 != nullptr && r2 != nullptr) {
            CM_EXPECT(r1->getStringAttribute("bus") == r2->getStringAttribute("bus"));
            CM_EXPECT(r1->getStringAttribute("direct") == r2->getStringAttribute("direct"));
            CM_EXPECT(r1->getStringAttribute("assign") == r2->getStringAttribute("assign"));
        }
    }

    // ---- the stored scene recalls its parameters and routing
    setActual(p, "fx.delay.timeMs", 100.0f);
    setActual(p, "input1.fxSend1", -40.0f);
    p.getRouting().setBus(5, 3, 0.0f);
    CM_EXPECT(p.getScenes().at(0).used && p.getScenes().at(0).name == "Golden A");
    CM_EXPECT(p.getScenes().recall(0, ScopeAll, 10.0f));
    CM_EXPECT_NEAR(actualOf(p, "fx.delay.timeMs"), 777.0, 0.5);
    CM_EXPECT_NEAR(actualOf(p, "input1.fxSend1"), -6.0, 0.02);
    CM_EXPECT_NEAR(p.getRouting().getBus(5, 3), busValue(5), 1e-3);
}
